export function initSupport({container,admin=false}){
 const box=document.createElement('details');box.className='support-panel';box.innerHTML='<summary>Atendimento por mensagem</summary><p class="support-intro"></p><p>Não envie senhas, códigos, dados de cartão ou chaves de acesso. As mensagens ficam vinculadas à sua conta.</p><button type="button" class="support-refresh">Atualizar conversas</button><div class="support-list" aria-label="Conversas"></div><div class="support-thread" hidden><h3 class="support-title"></h3><div class="support-messages" aria-label="Mensagens da conversa"></div><form class="support-reply"><label>Mensagem<textarea name="message" maxlength="2000" rows="4" required></textarea></label><button type="submit">Enviar mensagem</button></form></div><form class="support-new"><label>Nova conversa<textarea name="message" maxlength="2000" rows="4" required placeholder="Como podemos ajudar?"></textarea></label><small>Revise a mensagem antes de enviar. Ela não é enviada automaticamente.</small><button type="submit">Enviar ao atendimento</button></form><p class="support-status" role="status" aria-live="polite"></p>';if(admin&&container.querySelector('.dashboard-heading'))container.querySelector('.dashboard-heading').after(box);else container.append(box);
 const overview=document.createElement('span');overview.className='support-overview';overview.setAttribute('role','status');if(admin)box.querySelector('summary').append(overview);
 box.querySelector('.support-intro').textContent=admin?'Mensagens enviadas pelos clientes. Abra uma conversa para responder.':'Envie sua dúvida para a equipe. A resposta aparecerá aqui; volte para conferir.';box.querySelector('.support-new').hidden=admin;
 const $=selector=>box.querySelector(selector),status=$('.support-status'),list=$('.support-list'),thread=$('.support-thread'),messages=$('.support-messages'),reply=$('.support-reply'),newForm=$('.support-new');let current='',generation=0,busy=false,polling=false,timer=null,lastSignature='',overviewTimer=null,overviewVersion=0,overviewActive=false,overviewBusy=false;const drafts=new Map();
 const base='/api/support/'+(admin?'admin/':'');
 async function api(path,body){let r;try{r=await fetch(base+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});}catch{throw Error('Não foi possível conectar. Confira a conexão e tente novamente.');}const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Não foi possível carregar o atendimento agora.');return data;}
 function lock(on){busy=on;box.setAttribute('aria-busy',String(on));box.querySelectorAll('button').forEach(b=>b.disabled=on);}
 function reset({stopOverview=true}={}){generation++;if(stopOverview){overviewActive=false;overviewVersion++;overviewBusy=false;if(overviewTimer)clearInterval(overviewTimer);overviewTimer=null;overview.textContent='';}if(timer){clearInterval(timer);timer=null;}polling=false;lastSignature='';drafts.clear();current='';list.replaceChildren();messages.replaceChildren();reply.reset();newForm.reset();thread.hidden=true;status.textContent='';box.open=false;lock(false);}
 async function show(id,title,own){const data=await api('conversations/'+id+'/messages');if(own!==generation)return;if(current!==id){if(current)drafts.set(current,reply.elements.message.value);reply.elements.message.value=drafts.get(id)||'';}current=id;$('.support-title').textContent=title;const signature=JSON.stringify([id,data.messages]);const scrollTop=messages.scrollTop;if(signature!==lastSignature){lastSignature=signature;messages.replaceChildren();for(const message of data.messages){const article=document.createElement('article'),author=document.createElement('strong'),body=document.createElement('p');author.textContent=message.sender==='admin'?'Atendimento':'Cliente';body.textContent=message.body;article.append(author,body);messages.append(article);}messages.scrollTop=scrollTop;}thread.hidden=false;reply.hidden=data.status!=='open';}
 async function refresh(){const own=++generation;lock(true);status.textContent='Carregando conversas…';try{const data=await api('conversations');if(own!==generation)return;list.replaceChildren();if(!data.conversations.length){const p=document.createElement('p');p.textContent='Nenhuma conversa ainda.';list.append(p);}for(const item of data.conversations){const b=document.createElement('button');b.type='button';b.className='support-conversation';const title=(admin?item.email+' · ':'')+new Date(item.updated_at*1000).toLocaleString('pt-BR');b.textContent=title+(item.status==='closed'?' · Encerrada':admin&&item.waiting?' · Aguardando resposta':'');b.addEventListener('click',async()=>{const selected=++generation;lock(true);status.textContent='Abrindo conversa…';try{await show(item.id,title,selected);if(selected===generation)status.textContent='Conversa aberta.';}catch(e){if(selected===generation)status.textContent=e.message;}finally{if(selected===generation)lock(false);}});list.append(b);}if(current){const item=data.conversations.find(x=>x.id===current);if(item)await show(item.id,(admin?item.email+' · ':'')+new Date(item.updated_at*1000).toLocaleString('pt-BR'),own);else{current='';thread.hidden=true;messages.replaceChildren();}}if(own===generation)status.textContent='Conversas atualizadas.';}catch(e){if(own===generation)status.textContent=e.message;}finally{if(own===generation)lock(false);}}
 box.addEventListener('toggle',()=>{if(box.open){refresh();if(!timer)timer=setInterval(async()=>{if(!box.open||document.hidden||busy||polling||!current)return;polling=true;const own=generation,id=current,title=$('.support-title').textContent;try{await show(id,title,own);}catch{/* atualização manual continua disponível */}finally{polling=false;}},15000);}else reset({stopOverview:false});});$('.support-refresh').addEventListener('click',refresh);
 newForm.addEventListener('submit',async e=>{e.preventDefault();if(busy||!newForm.reportValidity())return;const text=newForm.elements.message.value.trim();if(!text){status.textContent='Escreva uma mensagem.';return;}const own=++generation;lock(true);status.textContent='Enviando…';try{const data=await api('conversations',{message:text});if(own!==generation)return;newForm.reset();if(current)drafts.set(current,reply.elements.message.value);current=data.id;reply.reset();await refresh();if(box.open)status.textContent='Mensagem enviada. Volte aqui para conferir a resposta.';}catch(error){if(own===generation)status.textContent=error.message;}finally{if(own===generation)lock(false);}});
 reply.addEventListener('submit',async e=>{e.preventDefault();if(busy||!current||!reply.reportValidity())return;const text=reply.elements.message.value.trim();if(!text){status.textContent='Escreva uma mensagem.';return;}const own=++generation,id=current;lock(true);status.textContent='Enviando…';try{await api('conversations/'+id+'/messages',{message:text});if(own!==generation)return;reply.reset();drafts.delete(id);await refresh();if(admin)updateOverview();if(box.open)status.textContent='Mensagem enviada.';}catch(error){if(own===generation)status.textContent=error.message;}finally{if(own===generation)lock(false);}});
 async function updateOverview(){if(!admin||!overviewActive||overviewBusy||document.hidden)return;overviewBusy=true;const own=overviewVersion;try{const data=await api('overview');if(own!==overviewVersion||!overviewActive)return;const count=Number(data.waiting);overview.textContent=Number.isInteger(count)&&count>=0?(count?' · '+count+' aguardando resposta':' · Nenhuma aguardando resposta'):' · Não foi possível verificar';}catch{if(own===overviewVersion&&overviewActive)overview.textContent=' · Não foi possível verificar';}finally{if(own===overviewVersion)overviewBusy=false;}}
 if(admin)document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateOverview();});
 function start(){if(!admin||overviewActive)return;overviewActive=true;overviewVersion++;overview.textContent=' · Verificando…';updateOverview();overviewTimer=setInterval(updateOverview,30000);}
 return {reset,start,open({draft=''}={}){if(!admin&&draft&&!newForm.elements.message.value.trim()){newForm.elements.message.value=draft;status.textContent='Revise sua mensagem e toque em enviar quando estiver pronta.';}box.open=true;box.querySelector('summary').focus();box.scrollIntoView({block:'nearest'});}};
}
